"use client";

import React, {
  createContext,
  useContext,
  useState,
  useEffect,
  ReactNode,
  useMemo,
  useCallback,
} from "react";
import { Auth, User, signInWithEmailAndPassword, signOut } from "firebase/auth";
import axios from "axios";
import { useFirebaseInit } from "@/hooks/useFirebaseInit";
import { useRouter } from "next/navigation";

// --- 設定 ---
const API_BASE_URL = process.env.NEXT_PUBLIC_API_BASE_URL;
axios.defaults.withCredentials = true;

// --- 型定義 ---
export interface AuthContextType {
  user: User | null;
  auth: Auth | null;
  userId: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  isLoggingOut: boolean;
  token: string | null;
  // ★修正1: loginの引数にnameを追加
  login: (credentials: {
    email: string;
    password: string;
    name?: string;
  }) => Promise<void>;
  logout: (redirectPath?: string) => Promise<void>;
  reloadAuthToken: () => Promise<void>;
}

const AuthContext = createContext<AuthContextType | null>(null);

// --- Auth Provider コンポーネント ---
export function AuthProvider({ children }: { children: ReactNode }) {
  const { auth, userId, isReady } = useFirebaseInit();
  const router = useRouter();

  const [user, setUser] = useState<User | null>(null);
  const [token, setToken] = useState<string | null>(null);
  const [isLoggingOut, setIsLoggingOut] = useState(false);

  const [laravelAuthenticated, setLaravelAuthenticated] = useState(false);
  const [initialCheckComplete, setInitialCheckComplete] = useState(false); // 初期チェック完了フラグ

  // Sanctum CSRF Cookieの取得
  const fetchCsrfCookie = useCallback(async () => {
    if (!API_BASE_URL) return;

    try {
      await axios.get(`${API_BASE_URL}/sanctum/csrf-cookie`);
      console.log("[Sanctum] CSRF cookie fetched");
    } catch (error) {
      console.error("[Sanctum] Failed to fetch CSRF cookie:", error);
    }
  }, []);

  // Laravel セッションチェック API
  const checkLaravelSession = useCallback(async () => {
    try {
      const res = await axios.get(`${API_BASE_URL}/api/auth/check`, {
        withCredentials: true,
      });
      return res.data; // { authenticated: boolean, user: { email_verified_at: string | null } } などを期待
    } catch {
      return { authenticated: false };
    }
  }, []);

  // Firebase ID TokenをLaravelに送り、Sanctumセッションを確立する
  const completeLaravelLogin = useCallback(
    // ★修正2: name を引数に追加
    async (idToken: string, name?: string) => {
      try {
        // ★修正3: name をペイロードに追加
        const payload = {
          id_token: idToken,
          ...(name && { name: name }),
        };

        const res = await axios.post(
          `${API_BASE_URL}/api/register_or_login`,
          payload
        );

        // サーバーから返されたユーザー情報（メール認証状態）を取得
        const backendUser = res.data.user;

        if (res.data.token && backendUser) {
          console.log(
            "[Sanctum] Successful token exchange and session established."
          );

          // 🚨 修正のポイント: サーバーからトークンが返されたらここでクライアント側のリダイレクト処理を行う 🚨
          if (!backendUser.email_verified_at) {
            console.log(
              "[Redirect] Email not verified. Moving to verification notice page."
            );
            // ★修正6: パスを "/verify-email-notice" に戻す
            router.push("/email/verify");
          } else {
            console.log("[Redirect] Email verified. Moving to dashboard.");
            router.push("/mypage");
          }

          return true; // 認証成功
        } else {
          throw new Error(
            "Sanctum token exchange failed: Missing token or user data."
          );
        }
      } catch (error) {
        console.error("[Sanctum] Token exchange error:", error);
        // 失敗時は再ログインを促すため、エラーをスロー
        throw error;
      }
    },
    [router]
  );

  /**
   * 認証トークンを強制的にリロードする関数
   */
  const reloadAuthToken = useCallback(async () => {
    if (user) {
      console.log("[Firebase] Forcing ID Token refresh...");
      try {
        const idToken = await user.getIdToken(true);
        setToken(idToken);
        // name はここでは渡さない (リフレッシュ目的のため)
        await completeLaravelLogin(idToken);
      } catch (error) {
        console.error("[Firebase] Failed to refresh ID Token:", error);
      }
    }
  }, [user, completeLaravelLogin]);

  // Firebase user 変化 → token 更新 + Laravel セッション確認
  useEffect(() => {
    if (!auth || !isReady) return;

    const unsub = auth.onAuthStateChanged(async (currentUser) => {
      setUser(currentUser);
      let idToken = null;
      let sessionData = { authenticated: false };

      if (currentUser) {
        try {
          idToken = await currentUser.getIdToken();
          setToken(idToken);
        } catch {
          setToken(null);
        }
      } else {
        setToken(null);
      }

      // 1. Firebaseユーザー変化のたび Laravel セッション確認
      sessionData = await checkLaravelSession();
      setLaravelAuthenticated(sessionData.authenticated);

      // 2. Firebaseユーザーが存在し、IDトークンがあり、かつLaravel側で認証されていない場合
      if (
        currentUser &&
        idToken &&
        !currentUser.isAnonymous &&
        !sessionData.authenticated
      ) {
        console.log(
          "[Sanctum] Non-anonymous user present but session missing. Attempting auto-login..."
        );
        try {
          // name は auto-login の際は渡さない
          const success = await completeLaravelLogin(idToken);
          if (success) {
            setLaravelAuthenticated(true);
          }
        } catch (error) {
          console.error(
            "[Sanctum] Auto-login attempt failed. Forcing Firebase logout."
          );
          await signOut(auth);
        }
      } else if (
        currentUser &&
        currentUser.isAnonymous &&
        sessionData.authenticated
      ) {
        console.warn(
          "[Sanctum] Anonymous user found with active Laravel session. Forcing logout."
        );
        await signOut(auth);
      }

      setInitialCheckComplete(true);
    });

    return () => unsub();
  }, [auth, isReady, checkLaravelSession, completeLaravelLogin]);

  // 初回 CSRF
  useEffect(() => {
    fetchCsrfCookie();
  }, [fetchCsrfCookie]);

  // isAuthenticated の正しい条件
  const isAuthenticated = useMemo(() => {
    return (
      initialCheckComplete &&
      !!user &&
      !user.isAnonymous &&
      laravelAuthenticated === true
    );
  }, [initialCheckComplete, user, laravelAuthenticated]);

  const isLoading = useMemo(
    () => !isReady || !initialCheckComplete,
    [isReady, initialCheckComplete]
  );

  // Login
  const login = useCallback(
    // ★修正4: credentials の型を AuthContextType に合わせて修正
    async ({ email, password, name }) => {
      if (!auth) throw new Error("Auth service unavailable.");

      await fetchCsrfCookie();
      const userCredential = await signInWithEmailAndPassword(
        auth,
        email,
        password
      );

      // Firebaseログイン成功後、IDトークンを使ってLaravel側にセッションを確立
      const idToken = await userCredential.user.getIdToken();

      // ★修正5: name を completeLaravelLogin に渡す
      await completeLaravelLogin(idToken, name);
      setLaravelAuthenticated(true);
    },
    [auth, fetchCsrfCookie, completeLaravelLogin]
  );

  // Logout
  const logout = useCallback(
    async (redirectPath = "/") => {
      if (!auth) return;

      setIsLoggingOut(true);
      try {
        await signOut(auth);
        setLaravelAuthenticated(false);
        router.push(redirectPath);
      } catch (e) {
        console.error("Logout failed:", e);
      } finally {
        setIsLoggingOut(false);
      }
    },
    [auth, router]
  );

  return (
    <AuthContext.Provider
      value={{
        user,
        auth,
        userId,
        isAuthenticated,
        isLoading,
        isLoggingOut,
        token,
        login,
        logout,
        reloadAuthToken,
      }}
    >
      {children}
    </AuthContext.Provider>
  );
}

export const useAuth = () => {
  const ctx = useContext(AuthContext);
  if (!ctx) throw new Error("useAuth must be used within AuthProvider");
  return ctx;
};
